                if dc % 2:
                    cc = -cc
                transformed.add((rr, cc))
            mr, mc = min(r for r, c in transformed), min(c for r, c in transformed)
            transformed = {(r-mr, c-mc) for r, c in transformed}
            th, tw = max(r for r,c in transformed)+1, max(c for r,c in transformed)+1
