def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    special = min((v for v in counts if v != 0 and v != background),
                  key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == special]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = {(r-r0, c-c0) for r, c in points}

    # All rotations and reflections of the marked pattern.
    variants = set()
    for reflected in (False, True):
        for k in range(4):
            pts = set()
            for r, c in shape:
                if reflected:
                    c = -c
                for _ in range(k):
                    r, c = c, -r
                pts.add((r, c))
            mr = min(r for r, c in pts)
            mc = min(c for r, c in pts)
            variants.add(frozenset((r-mr, c-mc) for r, c in pts))

    out = [row[:] for row in grid]
    for shape2 in variants:
        sh = max(r for r, c in shape2) + 1
        sw = max(c for r, c in shape2) + 1
        for r0 in range(h-sh+1):
            for c0 in range(w-sw+1):
                cells = [(r0+r, c0+c) for r, c in shape2]
                if all(grid[r][c] == 0 for r, c in cells):
                    for r, c in cells:
                        out[r][c] = special
    return out
